import{_ as e,V as o,W as a,a0 as p}from"./framework-9a29aaa0.js";const t={},r=p('<ul><li><a href="#cs-6824-%E7%AC%AC8%E8%AE%B2-zookeeper">cs-6.824 第8讲 zookeeper</a></li></ul><h1 id="cs-6-824-第8讲-zookeeper" tabindex="-1"><a class="header-anchor" href="#cs-6-824-第8讲-zookeeper" aria-hidden="true">#</a> cs-6.824 第8讲 zookeeper</h1><p>zookeeper基于Raft协议，具有分区容错性。</p><p>它运行将读操作分散到任意副本上进行，因此读取的内容可能不是最新的。另一方面，zookeeper确保每个副本按照顺序逐一处理写入流，所有副本均按照相同的顺序执行写操作。所有由单个客户端生成的读写操作，系统也会按照顺序处理。</p><p>zookeeper可以解决那些问题？</p><ul><li>VMWare VT test and set service</li><li>发布配置信息供其他服务器使用。</li></ul><p>Zookeeper的API像是一个文件系统，所以它拥有一个目录结构。</p><p>CREATE(path, data, flag)</p><p>DELETE(path, version)</p><p>EXISTS(path, watch);</p><p>example-count</p>',11),s=[r];function c(l,n){return o(),a("div",null,s)}const h=e(t,[["render",c],["__file","lesson8.html.vue"]]);export{h as default};
